(country, service) => {
  const props = [
    'display','position','boxSizing','width','height','minWidth','minHeight','maxWidth','maxHeight',
    'marginTop','marginRight','marginBottom','marginLeft','paddingTop','paddingRight','paddingBottom','paddingLeft',
    'gap','rowGap','columnGap','borderTopWidth','borderRightWidth','borderBottomWidth','borderLeftWidth',
    'borderTopColor','borderRightColor','borderBottomColor','borderLeftColor','borderTopLeftRadius','borderTopRightRadius','borderBottomRightRadius','borderBottomLeftRadius',
    'backgroundColor','backgroundImage','boxShadow','outline','outlineColor','outlineStyle','outlineWidth','outlineOffset',
    'color','fontFamily','fontSize','fontWeight','lineHeight','letterSpacing','textAlign','appearance','cursor','opacity','zIndex',
    'alignItems','justifyContent','flexDirection','flexGrow','flexShrink','overflow','transform'
  ];
  const describe = (el) => {
    if (!el) return null;
    const r = el.getBoundingClientRect();
    const cs = getComputedStyle(el);
    const style = {};
    props.forEach((p) => { style[p] = cs[p]; });
    return {
      tag: el.tagName,
      id: el.id,
      className: typeof el.className === 'string' ? el.className : el.className?.baseVal,
      role: el.getAttribute('role'),
      ariaLabel: el.getAttribute('aria-label'),
      value: el.value ?? null,
      rect: { x: r.x, y: r.y, top: r.top, right: r.right, bottom: r.bottom, left: r.left, width: r.width, height: r.height },
      style
    };
  };
  const commonAncestor = (a, b) => {
    const ancestors = [];
    let current = a;
    while (current) { ancestors.push(current); current = current.parentElement; }
    current = b;
    while (current && !ancestors.includes(current)) current = current.parentElement;
    return current;
  };
  const countryParent = country.parentElement;
  const serviceParent = service.parentElement;
  const row = commonAncestor(country, service);
  return {
    viewport: { innerWidth, innerHeight, devicePixelRatio, visualViewport: visualViewport ? { width: visualViewport.width, height: visualViewport.height, scale: visualViewport.scale } : null },
    activeElement: describe(document.activeElement),
    row: describe(row),
    rowChildren: Array.from(row.children).map(describe),
    country: describe(country),
    countryParent: describe(countryParent),
    countryParentChildren: Array.from(countryParent.children).map(describe),
    service: describe(service),
    serviceParent: describe(serviceParent),
    serviceParentChildren: Array.from(serviceParent.children).map(describe)
  };
}

(bookButton, country, service) => {
  const rect = (el) => { const r = el.getBoundingClientRect(); return {x:r.x,y:r.y,right:r.right,bottom:r.bottom,width:r.width,height:r.height}; };
  const style = (el) => { const cs=getComputedStyle(el); return {marginTop:cs.marginTop,marginBottom:cs.marginBottom,padding:cs.padding,gap:cs.gap,borderRadius:cs.borderRadius,boxShadow:cs.boxShadow,backgroundColor:cs.backgroundColor}; };
  const icon = (select) => select.parentElement.querySelector('svg');
  const iconInfo = (select) => {
    const svg=icon(select); const path=svg?.querySelector('path');
    return svg ? {tag:svg.tagName,rect:rect(svg),style:{color:getComputedStyle(svg).color,width:getComputedStyle(svg).width,height:getComputedStyle(svg).height},viewBox:svg.getAttribute('viewBox'),pathStroke:path?.getAttribute('stroke'),pathFill:path?.getAttribute('fill'),pathStrokeWidth:path?.getAttribute('stroke-width'),pathD:path?.getAttribute('d')} : null;
  };
  const row=country.parentElement.parentElement;
  return {
    bookButton:{rect:rect(bookButton),style:style(bookButton)},
    row:{rect:rect(row),style:style(row)},
    verticalGap:rect(row).y-rect(bookButton).bottom,
    countryIcon:iconInfo(country),
    serviceIcon:iconInfo(service)
  };
}

